<?php
$canOverrideConflict = (bool) ($canOverrideConflict ?? false);
$dayName = static fn (int $day): string => $days[$day] ?? 'Unknown';
$displayDate = static function (?string $date): string {
    if (!$date) {
        return '—';
    }
    $parsed = DateTimeImmutable::createFromFormat('!Y-m-d', $date);

    return $parsed ? $parsed->format('d-m-Y') : '—';
};
$displayTime = static fn (?string $time): string => $time ? substr($time, 0, 5) : '—';
$statusLabel = static fn (int $status): string => $status === 1 ? 'Approved' : ($status === 2 ? 'Pending approval' : 'Cancelled');
$pageUrl = static function (string $type, int $page) use ($scheduleFilters, $leaveFilters): string {
    $params = $type === 'schedule' ? [
        'schedule_search' => $scheduleFilters['search'], 'schedule_day' => $scheduleFilters['day'], 'schedule_status' => $scheduleFilters['status'], 'schedule_page_size' => $scheduleFilters['page_size'], 'schedule_page' => $page,
        'leave_search' => $leaveFilters['search'], 'leave_status' => $leaveFilters['status'], 'leave_page_size' => $leaveFilters['page_size'], 'leave_page' => $leaveFilters['page'],
    ] : [
        'schedule_search' => $scheduleFilters['search'], 'schedule_day' => $scheduleFilters['day'], 'schedule_status' => $scheduleFilters['status'], 'schedule_page_size' => $scheduleFilters['page_size'], 'schedule_page' => $scheduleFilters['page'],
        'leave_search' => $leaveFilters['search'], 'leave_status' => $leaveFilters['status'], 'leave_page_size' => $leaveFilters['page_size'], 'leave_page' => $page,
    ];

    return current_url() . '?' . http_build_query(array_filter($params, static fn ($value) => $value !== '' && $value !== 0));
};
?>
